<?php use App\adms\Helpers\CSRFHelper; $form = $this->data['form'] ?? []; ?>
<div class="container-fluid px-4"><h1 class="h3 mt-4 mb-3">Movimentações da Portaria</h1><?php include './app/adms/Views/partials/alerts.php'; ?>
<?php if (!empty($this->data['errors'])): ?><div class="alert alert-danger"><?= implode('<br>', array_map('htmlspecialchars', $this->data['errors'])) ?></div><?php endif; ?>
<?php if (!empty($this->data['warning'])): ?><div class="alert alert-warning"><strong><?= htmlspecialchars((string) $this->data['warning']) ?></strong><form method="post" class="row g-2 mt-2"><input type="hidden" name="csrf_token" value="<?= CSRFHelper::generateCSRFToken('form_portaria_movimentacao') ?>"><?php foreach (['visitante_id','autorizacao_id','ponto_controle_id','observacoes'] as $field): ?><input type="hidden" name="<?= $field ?>" value="<?= htmlspecialchars((string) ($form[$field] ?? '')) ?>"><?php endforeach; ?><input type="hidden" name="acao" value="regularizar"><div class="col-md-8"><input required class="form-control" name="motivo_regularizacao" placeholder="Motivo da saída não registrada"></div><div class="col-md-4"><button class="btn btn-warning">Regularizar saída e entrar</button></div></form></div><?php endif; ?>
<div class="card shadow-sm mb-4"><div class="card-header">Registrar entrada ou saída</div><div class="card-body"><form method="post"><input type="hidden" name="csrf_token" value="<?= CSRFHelper::generateCSRFToken('form_portaria_movimentacao') ?>"><div class="row g-3"><div class="col-md-5"><label class="form-label">Visitante *</label><select required class="form-select" name="visitante_id"><option value="">Selecione</option><?php foreach (($this->data['visitantes'] ?? []) as $v): ?><option value="<?= (int) $v['id'] ?>" <?= (int) ($form['visitante_id'] ?? 0) === (int) $v['id'] ? 'selected' : '' ?>><?= htmlspecialchars((string) $v['nome']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Autorização</label><select class="form-select" name="autorizacao_id"><option value="">Sem vínculo</option><?php foreach (($this->data['autorizacoes'] ?? []) as $a): ?><option value="<?= (int) $a['id'] ?>" <?= (int) ($form['autorizacao_id'] ?? 0) === (int) $a['id'] ? 'selected' : '' ?>><?= htmlspecialchars((string) $a['protocolo'] . ' — ' . (string) $a['visitante_nome']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Ponto *</label><select required class="form-select" name="ponto_controle_id"><option value="">Selecione</option><?php foreach (($this->data['pontos'] ?? []) as $p): ?><option value="<?= (int) $p['id'] ?>" <?= (int) ($form['ponto_controle_id'] ?? 0) === (int) $p['id'] ? 'selected' : '' ?>><?= htmlspecialchars((string) $p['nome']) ?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">Observações</label><input class="form-control" name="observacoes" value="<?= htmlspecialchars((string) ($form['observacoes'] ?? '')) ?>"></div></div><div class="mt-3"><button name="acao" value="entrada" class="btn btn-success">Registrar entrada</button> <button name="acao" value="saida" class="btn btn-danger">Registrar saída</button></div></form></div></div>
<div class="card shadow-sm"><div class="card-header">Presentes agora</div><div class="card-body table-responsive"><table class="table table-sm"><thead><tr><th>Visitante</th><th>Entrada</th><th>Ponto</th><th>Protocolo</th></tr></thead><tbody><?php foreach (($this->data['presentes'] ?? []) as $p): ?><tr><td><?= htmlspecialchars((string) $p['visitante_nome']) ?></td><td><?= htmlspecialchars((string) $p['ocorrido_em']) ?></td><td><?= htmlspecialchars((string) ($p['ponto_nome'] ?? '—')) ?></td><td><?= htmlspecialchars((string) ($p['protocolo'] ?? '—')) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
